import { type ChatInputCommandInteraction, SlashCommandBuilder } from "discord.js";

export interface Command {
  data: SlashCommandBuilder;
  execute: (interaction: ChatInputCommandInteraction) => Promise<void>;
}

/** Every slash command, one entry each. Run `npm run deploy-commands` after adding one. */
export const commands: Command[] = [
  {
    data: new SlashCommandBuilder().setName("ping").setDescription("Comprueba que el bot responde"),
    async execute(interaction) {
      await interaction.reply(`Pong (${interaction.client.ws.ping} ms)`);
    },
  },
];

import { Client, Events, GatewayIntentBits } from "discord.js";

import { commands } from "./commands.js";

const client = new Client({ intents: [GatewayIntentBits.Guilds] });
const byName = new Map(commands.map((c) => [c.data.name, c]));

client.once(Events.ClientReady, (c) => console.log(`Conectado como ${c.user.tag}`));

client.on(Events.InteractionCreate, async (interaction) => {
  if (!interaction.isChatInputCommand()) return;
  const command = byName.get(interaction.commandName);
  if (!command) return;
  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    const reply = { content: "Something went wrong running the command.", ephemeral: true };
    if (interaction.replied || interaction.deferred) await interaction.followUp(reply);
    else await interaction.reply(reply);
  }
});

client.login(process.env.DISCORD_TOKEN);

import { REST, Routes } from "discord.js";

import { commands } from "./commands.js";

const token = process.env.DISCORD_TOKEN!;
const clientId = process.env.DISCORD_CLIENT_ID!;

// Registers the slash commands globally (they can take a few minutes to show up).
await new REST().setToken(token).put(Routes.applicationCommands(clientId), { body: commands.map((c) => c.data.toJSON()) });
console.log(`${commands.length} comandos registrados`);
